-- M22 exact private schema, immutable artifact bindings, scoped APIs and ACLs. Read only.
DO $external_workflows_verify$
DECLARE actual jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=22 AND name='external_workflows') THEN RAISE EXCEPTION 'Missing external workflow migration22';END IF;
 SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',n.nspacl) ORDER BY n.nspname) FROM pg_namespace n WHERE n.nspname IN('forge_external_workflow','forge_external_workflow_api','forge_external_workflow_worker_api','forge_external_workflow_delivery_api')) source(value);
 IF encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM '509ff2e5e1f4600c9c9bab88b8a30d3568396465835ca81c54782664c8455a03' THEN RAISE EXCEPTION 'External workflow schemas catalog drift';END IF;
 SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'return',format_type(p.prorettype,NULL),'set',p.proretset,'secdef',p.prosecdef,'strict',p.proisstrict,'leakproof',p.proleakproof,'volatile',p.provolatile,'parallel',p.proparallel,'config',p.proconfig,'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'acl',p.proacl,'source',p.prosrc) ORDER BY n.nspname,p.proname,p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname IN('forge_external_workflow','forge_external_workflow_api','forge_external_workflow_worker_api','forge_external_workflow_delivery_api') AND NOT(n.nspname='forge_external_workflow' AND p.proname='immutable_plan_approve_override' AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=38 AND name='external_plan_approve_override'))) source(value);
 IF encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM '67617592efa9069d1ea7be5f14116dee2036e803c3ad0ba0c3e4f39c5c4830dc' THEN RAISE EXCEPTION 'External workflow functions catalog drift';END IF;
 IF EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=31) THEN
 SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated,(SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(a.attacl) x)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=30 AND name='agent_wide_retry_policy') AND c.relname='workflows' AND x.conname IN('workflows_plan_revisions_check','workflows_code_revisions_check') THEN replace(forge_agent._retry_legacy_constraint(x.conrelid,x.conname,pg_get_constraintdef(x.oid)),'<= 20','<= 3') ELSE forge_agent._retry_legacy_constraint(x.conrelid,x.conname,pg_get_constraintdef(x.oid)) END,x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),
 'acl',(SELECT jsonb_agg(entry ORDER BY entry::text) FROM unnest(c.relacl) entry WHERE entry::text<>'muse_events=r/forge_agent_owner'),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT(t.tgname='post_merge_external_confirmed' AND c.oid='forge_external_workflow.workflows'::regclass AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=28)))) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='forge_external_workflow'::regnamespace AND c.relkind IN('r','p','v','m','f','S') AND NOT(c.relname='plan_approve_overrides' AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=38 AND name='external_plan_approve_override'))) source(value);
 ELSE
 SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated,(SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(a.attacl) x)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=30 AND name='agent_wide_retry_policy') AND c.relname='workflows' AND x.conname IN('workflows_plan_revisions_check','workflows_code_revisions_check') THEN replace(pg_get_constraintdef(x.oid),'<= 20','<= 3') ELSE pg_get_constraintdef(x.oid) END,x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),
 'acl',(SELECT jsonb_agg(entry ORDER BY entry::text) FROM unnest(c.relacl) entry WHERE entry::text<>'muse_events=r/forge_agent_owner'),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT(t.tgname='post_merge_external_confirmed' AND c.oid='forge_external_workflow.workflows'::regclass AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=28)))) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='forge_external_workflow'::regnamespace AND c.relkind IN('r','p','v','m','f','S') AND NOT(c.relname='plan_approve_overrides' AND EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=38 AND name='external_plan_approve_override'))) source(value);
 END IF;
 IF encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM (CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=43) THEN '6c28d8da9e3ae9388aab4f3e2d17ddac967cd9bde2bbc804acfd61cc8e965854' ELSE '3100b7fc1c7fef83be0803b4f7523d3436ec80554381b6df09defd1a3a171dd1' END) THEN RAISE EXCEPTION 'External workflow relations catalog drift';END IF;
 IF EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=38 AND name='external_plan_approve_override') THEN
  SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'return',format_type(p.prorettype,NULL),'set',p.proretset,'secdef',p.prosecdef,'strict',p.proisstrict,'leakproof',p.proleakproof,'volatile',p.provolatile,'parallel',p.proparallel,'config',p.proconfig,'arguments',pg_get_function_arguments(p.oid),'result',pg_get_function_result(p.oid),'acl',p.proacl,'source',p.prosrc) ORDER BY n.nspname,p.proname,p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='forge_external_workflow' AND p.proname='immutable_plan_approve_override') source(value);
  IF encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM '9395c9535824501e8bec35fd2179a84d5d5e288c537760008fbf73f7834b5276' THEN RAISE EXCEPTION 'External plan approve-override function catalog drift';END IF;
  SELECT value INTO actual FROM (SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'persistence',c.relpersistence,'row_security',c.relrowsecurity,'force_row_security',c.relforcerowsecurity,
  'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid),a.attidentity,a.attgenerated,(SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(a.attacl) x)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(x.conname,x.contype,pg_get_constraintdef(x.oid),x.convalidated,x.condeferrable,x.condeferred) ORDER BY x.conname),'[]') FROM pg_constraint x WHERE x.conrelid=c.oid),
  'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_array(i.relname,pg_get_indexdef(i.oid),x.indisvalid,x.indisready) ORDER BY i.relname),'[]') FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid WHERE x.indrelid=c.oid),
  'acl',(SELECT jsonb_agg(entry ORDER BY entry::text) FROM unnest(c.relacl) entry),
  'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='forge_external_workflow'::regnamespace AND c.relname='plan_approve_overrides' AND c.relkind='r') source(value);
  IF encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM (CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=43) THEN '43f79444f756ea62e02f92d30a990b76e1e11e4d1f9165482405d987e89bdda3' ELSE 'baf9c551a62b19b1be0f7f34adb5699f03aea58f7c8df5509c86b46f2082398c' END) THEN RAISE EXCEPTION 'External plan approve-override relation catalog drift';END IF;
  IF NOT has_table_privilege('forge_agent','forge_external_workflow.plan_approve_overrides','SELECT')
     OR (CASE WHEN EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=43) THEN has_table_privilege('forge_agent','forge_external_workflow.plan_approve_overrides','INSERT') ELSE NOT has_table_privilege('forge_agent','forge_external_workflow.plan_approve_overrides','INSERT') END)
     OR has_table_privilege('forge_agent','forge_external_workflow.plan_approve_overrides','UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
     OR has_any_column_privilege('forge_agent','forge_external_workflow.plan_approve_overrides','UPDATE,REFERENCES')
     OR has_table_privilege('public','forge_external_workflow.plan_approve_overrides','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
     OR has_function_privilege('public','forge_external_workflow.immutable_plan_approve_override()','EXECUTE')
     OR has_table_privilege('forge_coding_worker','forge_external_workflow.plan_approve_overrides','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
     OR has_table_privilege('forge_coding_reconciler','forge_external_workflow.plan_approve_overrides','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
     OR (to_regrole('muse_events') IS NOT NULL AND has_table_privilege('muse_events','forge_external_workflow.plan_approve_overrides','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) THEN
   RAISE EXCEPTION 'Unexpected external plan approve-override privilege';
  END IF;
 END IF;
 IF EXISTS(SELECT FROM pg_class c,LATERAL aclexplode(c.relacl) a WHERE c.relnamespace='forge_external_workflow'::regnamespace AND a.grantee=to_regrole('muse_events') AND(a.privilege_type<>'SELECT' OR a.is_grantable OR a.grantor<>'forge_agent_owner'::regrole)) THEN RAISE EXCEPTION 'Unexpected external reader privilege';END IF;
END;
$external_workflows_verify$;
